actions.script:
// a ServiceJob runs with authorization off: the load is the user's, authorized as from the Tools app for all
// actions (the Data › Load transition), so entity authorization and the security checks of what it writes apply
ec.artifactExecution.runAsUser('component://tools/screen/Tools.xml', () => {
const runJob = (jobId) => {
    const out = ec.service.sync().name('org.moqui.impl.DatabaseServices.run#DatabaseJob').parameters({jobId, wait: true})
        .ignorePreviousError(true).call() || {}
    return out
}
loaded = false
recordsLoaded = 0
loadError = null

const dropped = runJob(dropJobId)
dropStatusId = dropped.statusId || null
if (dropStatusId == 'DbjsDone' && !ec.message.hasError()) {
    // the load, its errors kept apart so the restore runs
    try {
        if (loadKind == 'snapshot') {
            const out = ec.service.sync().name('org.moqui.impl.EntityServices.import#EntityDataSnapshot').parameters({zipFilename,
                dummyFks, useTryInsert, disableEntityEca, disableAuditLog, disableFkCreate, disableDataFeed,
                transactionTimeout: transactionTimeout || 3600}).call() || {}
            recordsLoaded = Number(out.recordsLoaded || 0)
        } else {
            const edl = ec.entity.makeDataLoader()
            if (types || components) {
                if (types) edl.dataTypes(String(types).split(','))
                if (components) edl.componentNameList(String(components).split(','))
            } else if (location) {
                if (/^https?:/i.test(String(location))) throw new Error('Remote data load location is not allowed')
                edl.location(location)
            } else if (csvText) edl.csvText(csvText)
            else if (jsonText) edl.jsonText(jsonText)
            else if (xmlText) edl.xmlText(xmlText)
            if (transactionTimeout) edl.transactionTimeout(transactionTimeout)
            if (dummyFks) edl.dummyFks(true)
            if (useTryInsert) edl.useTryInsert(true)
            if (onlyCreate) edl.onlyCreate(true)
            edl.restrictSensitiveEntities(true)
            recordsLoaded = edl.load([])
        }
        loaded = !ec.message.hasError()
    } catch (e) {
        loadError = String(e.message || e)
    }
    if (ec.message.hasError()) loadError = [loadError, ec.message.errorsString].filter(Boolean).join('; ')
} else {
    loadError = 'Not loaded: dropping the foreign keys ended ' + (dropStatusId || 'with an error') + ' (database job ' + dropJobId + ')'
}

// always: the keys come back whatever the drop or the load did
const restored = runJob(restoreJobId)
restoreStatusId = restored.statusId || null
restoreFailedCount = Number(restored.failedCount || 0)
outcome = (loaded ? 'Loaded ' + recordsLoaded + ' records' : (loadError || 'Not loaded')) + '. Restoring the foreign keys (database job '
    + restoreJobId + ') ended ' + (restoreStatusId || 'with an error') + (restoreFailedCount ? ', ' + restoreFailedCount + ' failed' : '') + '.'
if (restoreStatusId == 'DbjsDone') ec.logger.info('Load wrap: ' + outcome)
else ec.logger.error('Load wrap: ' + outcome + ' Run database job ' + restoreJobId + ' again to make the rest of the keys.')
// the outcome is the job run's results; the load's error is not the run's, as the restore did run
ec.message.clearErrors()
if (!loaded || restoreStatusId != 'DbjsDone') ec.message.addError(outcome)
})
